const $=id=>document.getElementById(id),engine=QueueEngine;
const models=[['MM1','M/M/1','Um servidor, capacidade e população ilimitadas.'],['MMs','M/M/s > 1','Vários servidores em paralelo, capacidade ilimitada.'],['MM1K','M/M/1/K','Um servidor e capacidade total K. Chegadas com o sistema cheio são recusadas.'],['MMsK','M/M/s > 1/K','Vários servidores e capacidade total K, incluindo o atendimento.'],['MM1N','M/M/1/N','Um servidor e população finita N de clientes.'],['MMsN','M/M/s > 1/N','Vários servidores e população finita N de clientes.'],['MG1','M/G/1','Um servidor e atendimento com distribuição geral.'],['PRIORITY','Prioridades','Classes com ou sem interrupção do atendimento.']];
const units={hora:3600,minuto:60,segundo:1,dia:86400,mes:2592000};
const fields={
 lambda:['Taxa de chegada','λ','rate'],mu:['Taxa de atendimento por servidor','μ','rate'],tmc:['Tempo médio entre chegadas','TMC = 1/λ','time'],tms:['Tempo médio de atendimento','TMS = 1/μ','time'],
 L:['Clientes no sistema','L = E(q)','count'],Lq:['Clientes aguardando na fila','Lq = E(w)','count'],W:['Tempo médio no sistema','W = E(tq)','time'],Wq:['Espera média na fila','Wq = E(tw)','time'],rho:['Ocupação média por servidor','λef/(sμ)','percent'],p0:['Probabilidade de sistema vazio','P₀','percent'],
 load:['Razão de taxas · ρ no formulário','λ/μ','number'],U:['Probabilidade de sistema ocupado','U = 1 − P₀','percent'],effective:['Taxa efetiva de chegada','λef','rate'],busy:['Clientes em atendimento','E(S)','count'],block:['Probabilidade de bloqueio','Pbloqueio','percent'],wait:['Probabilidade de esperar ao entrar','Pespera','percent'],
 cv:['Coeficiente de variação','CV = σ/E(ts)','number'],sd:['Desvio padrão do atendimento','σ','time'],variance:['Variância do atendimento','σ²','squared'],second:['Segundo momento do atendimento','E[ts²]','squared']};
let model=null,timer,epoch=0,observed={},last=null;
const unitName=()=> $('unit').value==='mes'?'mês':$('unit').value;
const f=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:5}),pct=n=>(n*100).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%',time=n=>f(n)+' '+($('unit').value==='mes'?(Math.abs(n-1)<1e-8?'mês':'meses'):unitName()+(Math.abs(n-1)<1e-8?'':'s'));
const options=selected=>Object.keys(units).map(u=>`<option value="${u}" ${u===selected?'selected':''}>${u==='mes'?'Mês (30 dias)':u[0].toUpperCase()+u.slice(1)}</option>`).join('');
function field(key){const [label,symbol,type]=fields[key];const unit=['time','rate','squared'].includes(type)?`<label class="sr" for="${key}-unit">Unidade de ${label}</label><select id="${key}-unit" data-unit="${key}" aria-label="Unidade de ${label}">${options('hora')}</select>`:`<span class="field-suffix">${type==='percent'?'%':type==='count'?'clientes':'sem unidade'}</span>`;return `<div class="data-field"><label for="${key}">${label}<small>${symbol}</small></label><div class="value-unit"><input id="${key}" data-key="${key}" inputmode="decimal" autocomplete="off" placeholder="Não informado">${unit}</div>${type==='rate'?'<span class="unit-hint">clientes por unidade de tempo</span>':type==='squared'?'<span class="unit-hint">unidade de tempo ao quadrado</span>':''}</div>`;}
function buildFields(){
 $('priority-fields').hidden=model!=='PRIORITY';
 for(const el of $('form').querySelectorAll('.data-group,.extra-details,.count-details'))el.hidden=model==='PRIORITY';
 if(model==='PRIORITY'){buildPriorityFields();return;}
 $('basic-fields').innerHTML=['lambda','mu','tmc','tms'].map(field).join('');
 $('measure-fields').innerHTML=['L','Lq','W','Wq','rho','p0'].map(field).join('');
 $('variance-fields').innerHTML=['cv','sd','variance','second'].map(field).join('');
 $('extra-fields').innerHTML=['load','U','effective','busy',...(model.endsWith('K')?['block']:[]),'wait'].map(field).join('');
 $('count-fields').innerHTML=['arrival','service'].map(key=>`<div class="observation"><h3>${key==='arrival'?'Chegadas observadas'+(model.endsWith('N')?' por cliente fora do sistema':''):'Atendimentos observados por servidor'}</h3><div class="field-grid"><div><label for="${key}-count">Quantidade de clientes</label><input id="${key}-count" inputmode="decimal" placeholder="Não informado"></div><div><label for="${key}-period">Duração do intervalo</label><div class="value-unit"><input id="${key}-period" inputmode="decimal" placeholder="Não informado"><select id="${key}-period-unit" aria-label="Unidade do intervalo de ${key==='arrival'?'chegadas':'atendimentos'}">${options('hora')}</select></div></div></div></div>`).join('');
}
function route(){
 clearTimeout(timer);epoch++;const key=decodeURIComponent(location.hash.replace(/^#\/?/,''));const chosen=models.find(x=>key==='modelo/'+x[0]);
 $('choose-page').hidden=!!chosen;$('calculator-page').hidden=!chosen;$('example').hidden=!chosen;$('print').hidden=!chosen;
 if(!chosen){model=null;document.title='Filas Lab — Escolha o modelo';return;}
 if(model!==chosen[0]){model=chosen[0];$('form').reset();buildFields();$('s-wrap').hidden=!(model.includes('s')||model==='PRIORITY');$('cap-wrap').hidden=!/[KN]$/.test(model);$('cap-label').textContent=model.endsWith('N')?'População finita · N':'Capacidade total · K';$('source-note').hidden=!model.endsWith('N');$('variability').hidden=model!=='MG1';}
 $('model-title').textContent=chosen[1];$('description').textContent=chosen[2];document.title=chosen[1]+' — Filas Lab';resetResults();$('model-title').focus({preventScroll:true});window.scrollTo(0,0);run();
}
function value(id){const raw=$(id).value.trim();if(raw==='')return undefined;const n=Number(raw.replace(',','.'));if(!Number.isFinite(n))throw Error('Preencha '+($(id).labels?.[0]?.textContent||id)+' com um número válido, usando vírgula ou ponto decimal.');return n;}
function syncMGService(){
 if(model!=='MG1')return;
 const kind=$('mg-service').value;
 $('cv').readOnly=kind!=='general';
 if(kind!=='general')$('cv').value=kind==='exponential'?'1':'0';
 $('mg-service-note').textContent=kind==='exponential'?'Atendimento exponencial: CV = 1 automaticamente, pois o desvio padrão é igual à média.':kind==='constant'?'Atendimento constante: CV = 0 automaticamente, pois não há variação no tempo de atendimento.':'Informe CV, desvio padrão, variância ou segundo momento se o exercício fornecer esses dados.';
}
function collect(){
 syncMGService();
 const outputSeconds=units[$('unit').value],data={};
 function add(key,n,source){if(n===undefined)return;if(data[key]!==undefined&&Math.abs(n-data[key])>1e-7+.005*Math.max(Math.abs(n),Math.abs(data[key])))throw Error('Dados incompatíveis: '+source+' não corresponde a '+QueueSolver.names[key]+'. Confira os valores e as unidades.');if(data[key]===undefined)data[key]=n;}
 for(const el of $('form').querySelectorAll('[data-key]')){const key=el.dataset.key;if(['cv','sd','variance','second'].includes(key)&&model!=='MG1')continue;let n=value(key);if(n===undefined)continue;if(n<0)throw Error('O campo '+fields[key][0]+' não pode ser negativo.');const type=fields[key][2],factor=$(key+'-unit')?units[$(key+'-unit').value]/outputSeconds:1;
 if(type==='percent')n/=100;if(type==='rate')n/=factor;if(type==='time')n*=factor;if(type==='squared')n*=factor*factor;
 if(key==='tmc'||key==='tms'){if(n<=0)throw Error('Os tempos médios entre chegadas e de atendimento devem ser maiores que zero.');add(key==='tmc'?'lambda':'mu',1/n,fields[key][0]);}else add(key,n,fields[key][0]);}
 for(const key of ['arrival','service']){const n=value(key+'-count'),period=value(key+'-period');if(n===undefined&&period===undefined)continue;if(n===undefined||period===undefined)throw Error('Para usar uma contagem, informe a quantidade e a duração do intervalo.');if(n<=0||period<=0)throw Error('A contagem e a duração do intervalo devem ser maiores que zero.');add(key==='arrival'?'lambda':'mu',n/period*outputSeconds/units[$(key+'-period-unit').value],key==='arrival'?'Contagem de chegadas':'Contagem de atendimentos');}
 return data;
}
function resetResults(){last=null;$('output').innerHTML='';$('error').hidden=true;$('status').textContent='Aguardando dados';$('feedback').textContent='Os campos começam vazios. Preencha os dados conhecidos para ver o que já pode ser calculado.';}
function run(){
 if(!model)return;try{$('month-note').hidden=![...$('form').querySelectorAll('select')].some(el=>el.value==='mes');if(model==='PRIORITY'){runPriority();return;}observed=collect();const config={model,s:model.includes('s')?value('s'):1};if(model.endsWith('K'))config.K=value('cap');if(model.endsWith('N'))config.N=value('cap');
 if((model.includes('s')&&config.s===undefined)||(/[KN]$/.test(model)&&value('cap')===undefined)){$('output').innerHTML='';$('error').hidden=true;$('status').textContent='Defina o sistema';$('feedback').textContent='Informe '+[model.includes('s')?'o número de servidores s':null,model.endsWith('K')?'a capacidade total K':model.endsWith('N')?'a população N':null].filter(Boolean).join(' e ')+'. Depois, preencha os dados que conhece.';last=null;return;}
 if(!Object.keys(observed).length){resetResults();return;}
 const solution=QueueSolver.solve(config,observed);last={solution,config};$('error').hidden=true;$('status').textContent=solution.kind==='complete'?'Cálculo completo':'Cálculo parcial';$('feedback').textContent=solution.kind==='complete'?'Os dados preenchidos foram suficientes para calcular o sistema.':solution.message;render(solution,config);
 }catch(e){last=null;$('output').innerHTML='';$('feedback').textContent='';$('status').textContent='Confira os dados';$('error').textContent=e.message;$('error').hidden=false;}
}
function render(solution,config){const v=solution.values,complete=solution.kind==='complete';
 const definitions=[['lambda','Taxa de chegada','λ','rate'],['mu','Atendimento por servidor','μ','rate'],['effective','Taxa efetiva de chegada','λef','rate'],['L','Clientes no sistema','L = E(q)','count'],['Lq','Clientes aguardando na fila','Lq = E(w)','count'],['busy','Clientes em atendimento','E(S)','count'],['W','Tempo médio no sistema','W = E(tq)','time'],['Wq','Espera média na fila','Wq = E(tw)','time'],['load','Razão λ/μ · ρ no formulário','λ/μ','number'],['rho','Ocupação média por servidor','λef/(sμ)','percent'],['U','Sistema ocupado','U = 1 − P₀','percent'],['p0','Sistema vazio','P₀','percent'],['block','Probabilidade de bloqueio','Pbloqueio','percent'],['wait','Chance de esperar ao entrar','Pespera','percent'],...(model==='MG1'?[['cv','Coeficiente de variação','CV','number'],['sd','Desvio padrão do atendimento','σ','time'],['variance','Variância do atendimento','σ²','squared'],['second','Segundo momento do atendimento','E[ts²]','squared']]:[])];
 const rows=definitions.filter(([key])=>v[key]!==undefined&&v[key]!==null).map(([key,label,sym,type])=>{const val=type==='percent'?pct(v[key]):type==='time'?time(v[key]):type==='rate'?f(v[key])+' /'+unitName():type==='squared'?f(v[key])+' '+unitName()+'²':f(v[key]);return `<tr><td><span class="result-symbol">${sym}</span>${label}<small class="result-origin">${observed[key]!==undefined?'Informado':'Calculado'}</small></td><td>${val}${type==='count'?'<small> clientes</small>':''}</td></tr>`;}).join('');
 $('output').innerHTML=`${rows?`<table class="result-table"><thead><tr><th scope="col">Medida</th><th scope="col">Valor</th></tr></thead><tbody>${rows}</tbody></table>`:''}${v.mu?`<p class="hint">Tempo médio de atendimento (1/μ): ${time(1/v.mu)}.</p>`:''}${v.lambda?`<p class="hint">Tempo médio entre chegadas (1/λ): ${time(1/v.lambda)}${model.endsWith('N')?' por cliente fora do sistema':''}.</p>`:''}${solution.steps.length?`<details><summary>Como os dados foram relacionados</summary><ol>${solution.steps.map(x=>'<li>'+x+'</li>').join('')}</ol></details>`:''}${complete?`<details><summary>Fórmulas deste modelo</summary><p class="formula">${v.method}</p><p>Lei de Little: L = λef W; Lq = λef Wq. Atendimento: W = Wq + 1/μ. E(S) = L − Lq = λef/μ. Nos modelos com população finita, λ é por cliente fora do sistema.</p></details>`:''}<details><summary>Referências e notação</summary><p>Formulário M008 Capítulo 7, páginas 1–3; Teoria das filas Modelo MMs, páginas 20–50; Modelo MMsK e MMsN, páginas 3–24; Modelo MG1 e com prioridades, páginas 3–20, Prof. Dr. Paulo Roberto Maia. Validação ampliada pelas quatro listas de exercícios correspondentes.</p><p>Equivalências: E(q) = L; E(w) = Lq; E(tq) = W; E(tw) = Wq; E(S) = número em atendimento. O ρ do formulário é λ/μ, não a ocupação por servidor. K é capacidade total; N é população finita.</p><p>Dados adicionais são conferidos com tolerância relativa de 0,5% para arredondamentos. Os resultados usam as equações do modelo; dados ausentes não recebem valores padrão.</p></details>`;
 if(complete&&v.probs)probabilities(v,config);
 if(complete&&(model==='MM1'||model==='MMs')){tails(v);poissonQueries(v);}
 if(complete&&model.endsWith('N'))$('output').insertAdjacentHTML('beforeend',`<p class="hint">Clientes em operação: ${f(config.N-v.L)} de ${config.N}. Disponibilidade individual: ${pct(1-v.L/config.N)}. Ociosidade média por servidor: ${pct(1-v.rho)}. Todos os servidores ociosos: ${pct(v.p0)}.</p>`);
 if(complete&&model.endsWith('K'))$('output').insertAdjacentHTML('beforeend',`<p class="hint">Chegadas recusadas: ${f(v.lambda*v.block)} /${unitName()}. Sistema ocupado: ${pct(v.U)}; sistema cheio: ${pct(v.block)}.</p>`);
 if(model==='MG1'){$('output').insertAdjacentHTML('beforeend','<p class="hint">Em M/G/1, média e variância não determinam toda a distribuição P(n). A chance de esperar é igual à ocupação do servidor.</p>');}
}
function probabilities(r,config){
 const box=document.createElement('details');box.innerHTML='<summary>Consultar probabilidade P(n)</summary><label for="query-n">Número de clientes no sistema · n</label><input id="query-n" inputmode="numeric" value="0"><p id="pn"></p><p class="hint">P(n) é a probabilidade de haver exatamente n clientes no sistema.</p>';
 box.innerHTML+=`<div class="chart" role="img" aria-label="Probabilidades de zero a ${Math.min(r.probs.length,30)-1} clientes no sistema">${r.probs.slice(0,30).map((p,n)=>`<div class="bar" style="height:${Math.max(.4,p/Math.max(...r.probs)*100)}%" title="P(${n}) = ${pct(p)}"></div>`).join('')}</div><p class="chart-note">Barras: n = 0 a ${Math.min(r.probs.length,30)-1}. ${!/[KN]$/.test(model)?'A tabela mostra um trecho da distribuição infinita.':''}</p><div style="max-height:220px;overflow:auto"><table><thead><tr><th>n</th><th>P(n)</th></tr></thead><tbody>${r.probs.map((p,n)=>`<tr><td>${n}</td><td>${pct(p)}</td></tr>`).join('')}</tbody></table></div>`;$('output').append(box);
 function show(){try{$('pn').textContent=`P(${value('query-n')}) = ${pct(engine.probability(r,value('query-n')))}`;}catch(e){$('pn').textContent=e.message;}};$('query-n').oninput=show;show();
 countQueries(r);
}
function tails(r){const box=document.createElement('details');box.innerHTML='<summary>Probabilidades de exceder um limite</summary><label for="threshold">Limite de clientes · r</label><input id="threshold" inputmode="numeric" value="0"><label for="limit">Tempo · '+unitName()+'</label><input id="limit" inputmode="decimal" value="0"><p id="tails"></p>';$('output').append(box);const show=()=>{try{const v=engine.tails(r,value('limit'),value('threshold'));$('tails').textContent='P(n > r) = '+pct(v.count)+' · P(W > t) = '+pct(v.system)+' · P(Wq > t) = '+pct(v.queue);}catch(e){$('tails').textContent=e.message;}};$('limit').oninput=show;$('threshold').oninput=show;show();}
function schedule(){clearTimeout(timer);last=null;$('output').innerHTML='';$('error').hidden=true;$('status').textContent='Atualizando';$('feedback').textContent='Relacionando os dados preenchidos…';const current=++epoch;timer=setTimeout(()=>{if(epoch===current)run();},400);}
function clear(){clearTimeout(timer);epoch++;$('form').reset();if(model==='PRIORITY')buildPriorityFields();resetResults();run();}
function countQueries(r){
 const box=document.createElement('details');box.innerHTML=`<summary>Comparar quantidade de clientes</summary><label for="count-scope">Onde contar</label><select id="count-scope"><option value="system">No sistema (fila e atendimento)</option><option value="queue">Somente aguardando na fila</option></select><label for="count-relation">Comparação</label><select id="count-relation"><option value="le">No máximo (≤)</option><option value="lt">Menos de (&lt;)</option><option value="eq">Exatamente (=)</option><option value="ge">Pelo menos (≥)</option><option value="gt">Mais de (&gt;)</option></select><label for="count-limit">Quantidade de clientes</label><input id="count-limit" inputmode="numeric" value="0"><p id="count-answer" role="status"></p>`;$('output').append(box);
 const show=()=>{try{$('count-answer').textContent='Probabilidade: '+pct(engine.countProbability(r,value('count-limit'),$('count-relation').value,$('count-scope').value));}catch(e){$('count-answer').textContent=e.message;}};
 box.addEventListener('input',show);box.addEventListener('change',show);show();
}
function poissonQueries(r){
 const box=document.createElement('details');box.innerHTML=`<summary>Contagens de Poisson em um intervalo</summary><label for="poisson-kind">Evento</label><select id="poisson-kind"><option value="arrival">Chegadas</option><option value="service">Atendimentos potenciais por servidor</option></select><label for="poisson-period">Duração · ${unitName()}</label><input id="poisson-period" inputmode="decimal" value="1"><label for="poisson-n">Quantidade exata de eventos</label><input id="poisson-n" inputmode="numeric" value="0"><p id="poisson-answer" role="status"></p><p class="hint">Atendimentos potenciais pressupõem um servidor trabalhando continuamente durante todo o intervalo. Não representam as saídas reais de um servidor que pode ficar ocioso.</p>`;$('output').append(box);
 const show=()=>{try{$('poisson-answer').textContent='Probabilidade: '+pct(engine.poisson($('poisson-kind').value==='arrival'?r.lambda:r.mu,value('poisson-period'),value('poisson-n')));}catch(e){$('poisson-answer').textContent=e.message;}};
 box.addEventListener('input',show);box.addEventListener('change',show);show();
}
function buildPriorityFields(){
 $('priority-fields').innerHTML=`<label for="pr-discipline">Disciplina de prioridade</label><select id="pr-discipline"><option value="nonpreemptive">Sem interrupção</option><option value="preemptive">Com interrupção e retomada</option></select><p class="hint">Sem interrupção: quem está em atendimento termina primeiro. Com interrupção: o atendimento de menor prioridade é suspenso e retomado depois.</p><label for="pr-service">Atendimento</label><select id="pr-service"><option value="common">Exponencial · taxa única</option><option value="general">Geral · taxa por classe</option></select><div id="pr-common"><label for="pr-mu">Taxa de atendimento por servidor · μ /<span class="pr-unit">${unitName()}</span></label><input id="pr-mu" inputmode="decimal" placeholder="Não informado"></div><label for="pr-count">Número de classes</label><select id="pr-count">${Array.from({length:9},(_,i)=>`<option value="${i+2}">${i+2}</option>`).join('')}</select><p class="hint">Classe 1 é a maior prioridade. Atendimento geral exige um servidor, sem interrupção, e média e variância por classe. Todas as taxas e variâncias usam a unidade dos resultados; variâncias usam essa unidade ao quadrado.</p><div id="pr-classes"></div>`;
 function rows(){
  const old=[...$('pr-classes').querySelectorAll('input')].map(el=>[el.id,el.value]);
  $('pr-classes').innerHTML=Array.from({length:Number($('pr-count').value)},(_,i)=>`<fieldset class="priority-class"><legend>Classe ${i+1}${i===0?' · maior prioridade':''}</legend><label for="pr-lambda-${i}">Taxa de chegada · λ${i+1}</label><input id="pr-lambda-${i}" inputmode="decimal" placeholder="Não informado"><div class="pr-general" ${$('pr-service').value==='common'?'hidden':''}><label for="pr-mu-${i}">Taxa média de atendimento · μ${i+1}</label><input id="pr-mu-${i}" inputmode="decimal" placeholder="Não informado"><label for="pr-variance-${i}">Variância do atendimento · σ²${i+1}</label><input id="pr-variance-${i}" inputmode="decimal" placeholder="Não informado"></div></fieldset>`).join('');
  for(const [id,val] of old)if($(id))$(id).value=val;
 }
 $('pr-count').addEventListener('change',rows);
 $('pr-service').addEventListener('change',()=>{$('pr-common').hidden=$('pr-service').value!=='common';rows();});rows();
}
function runPriority(){
 for(const el of document.querySelectorAll('.pr-unit'))el.textContent=unitName();
 const general=$('pr-service').value==='general',s=value('s'),mu=general?undefined:value('pr-mu');
 const classes=Array.from({length:Number($('pr-count').value)},(_,i)=>({lambda:value('pr-lambda-'+i),...(general?{mu:value('pr-mu-'+i),variance:value('pr-variance-'+i)}:{})}));
 if(s===undefined||(!general&&mu===undefined)||classes.some(c=>c.lambda===undefined||(general&&(c.mu===undefined||c.variance===undefined)))){
  resetResults();$('status').textContent='Defina as classes';$('feedback').textContent='Informe o número de servidores e as taxas de todas as classes. Para atendimento geral, informe também a variância de cada classe (zero para atendimento constante).';return;
 }
 const r=engine.priorities({classes,s,mu,discipline:$('pr-discipline').value});last={priority:r};$('error').hidden=true;$('status').textContent='Cálculo completo';$('feedback').textContent='Resultados por classe, da maior para a menor prioridade.';
 $('output').innerHTML=`<div class="priority-table"><table><caption>Medidas por classe · tempos em ${unitName()}</caption><thead><tr><th scope="col">Classe</th><th scope="col">L</th><th scope="col">Lq</th><th scope="col">W</th><th scope="col">Wq</th></tr></thead><tbody>${r.classes.map(c=>`<tr><th scope="row">${c.priority}</th><td>${f(c.L)}</td><td>${f(c.Lq)}</td><td>${f(c.W)}</td><td>${f(c.Wq)}</td></tr>`).join('')}</tbody></table></div><p class="hint">L: clientes no sistema; Lq: clientes aguardando; W: tempo no sistema; Wq: tempo sem atendimento ativo, incluindo suspensões quando há interrupção.</p><table class="result-table"><tbody>${[['Chegadas totais',f(r.lambda)+' /'+unitName()],['Ocupação média por servidor',pct(r.rho)],['Clientes no sistema · L',f(r.L)],['Clientes na fila · Lq',f(r.Lq)],['Tempo médio no sistema · W',time(r.W)],['Tempo médio na fila · Wq',time(r.Wq)],['Sistema vazio · P₀',pct(r.p0)]].map(([label,val])=>`<tr><td>${label}</td><td>${val}</td></tr>`).join('')}</tbody></table><details><summary>Fórmulas e hipóteses</summary><p>Chegadas independentes de Poisson; capacidade ilimitada; classe 1 tem maior prioridade; FCFS dentro de cada classe.</p><p>${r.discipline==='preemptive'?'Com interrupção e retomada, atendimento exponencial idêntico: cada conjunto acumulado de classes forma um M/M/s. Lk = L(λ₁ + … + λk) − L(λ₁ + … + λk₋₁); Wk = Lk/λk; Wqk = Wk − 1/μ.':'Sem interrupção: Wqk = R / [(1 − Ak₋₁)(1 − Ak)], com Ak = Σ λi/(sμ). Para exponenciais idênticas, R = Erlang C/(sμ). Para atendimento geral com s = 1, Ak = Σ λi/μi e R = Σ λi(σi² + 1/μi²)/2. Wk = Wqk + 1/μk; Lk = λkWk; Lqk = λkWqk.'}</p><p>Fonte: Teoria das filas Modelo MG1 e com prioridades, páginas 8–20, e lista de exercícios correspondente. Os cálculos usam a taxa de cada classe, inclusive nos resultados L e Lq.</p></details>`;
}

